css:
.t{background:#0b0b10;font-family:Poppins,Arial,sans-serif;color:#fff}
.bg{position:absolute;inset:0;background:
  radial-gradient(520px 360px at 82% 96%, rgba(104,24,231,.55), rgba(104,24,231,0) 70%),
  radial-gradient(420px 300px at 62% 58%, rgba(71,55,228,.20), rgba(71,55,228,0) 70%),
  radial-gradient(700px 420px at 12% 0%, rgba(40,30,90,.35), rgba(40,30,90,0) 70%)}
.wave{position:absolute;left:-40px;top:250px;width:1300px;height:380px;opacity:.55}
.bar{position:absolute;left:0;top:0;width:6px;height:628px;background:#6818e7}
.left{position:absolute;left:64px;top:56px;width:560px;height:516px;display:flex;flex-direction:column;justify-content:flex-end;gap:29px;padding-bottom:67px}
.logo{position:absolute;left:66px;top:91px;width:149px}
.logo img{width:149px;height:auto}
.logo .wb{font:700 9.5px/1 Poppins;letter-spacing:.9px;text-align:right;margin-top:4px;padding-right:2px}
.eyebrow{align-self:flex-start;display:flex;align-items:center;gap:8px;height:34px;padding:0 16px 0 13px;border-radius:100px;background:rgba(185,166,255,.14);border:1px solid rgba(185,166,255,.5);color:#b9a6ff;font:600 13px/1 Poppins;letter-spacing:1.5px;text-transform:uppercase;white-space:nowrap}
.eyebrow i{width:6px;height:6px;border-radius:50%;background:#b9a6ff;display:block}
.title{font:600 52px/1.24 Poppins;letter-spacing:-.02em;color:#fff;max-height:130px;overflow:hidden}
.title .hl{color:#b9a6ff}
.meta{display:flex;align-items:center;gap:32px;font:500 16px/1 Poppins;color:#fff;margin-top:-4px}
.meta span{display:flex;align-items:center;gap:8px;white-space:nowrap}
.meta svg{width:22px;height:22px;stroke:#fff;fill:none;stroke-width:1.7}
.cta{align-self:flex-start;padding:15px 28px;border-radius:12px;background:linear-gradient(90deg,#4737e4,#6918e8);font:700 17px/1 Poppins;color:#fff;box-shadow:0 8px 24px rgba(105,24,232,.35)}
.right{position:absolute;right:64px;top:56px;width:502px;height:516px;display:flex;flex-direction:column;justify-content:center;gap:14px}
.right .lbl{font:600 15px/1 Poppins;letter-spacing:1px;color:#b8b8c7;margin-bottom:2px}
.card{display:flex;align-items:center;gap:16px;height:108px;padding:16px;border-radius:16px;background:rgba(10,10,10,.42);border:1px solid rgba(255,255,255,.1)}
.few .card{height:132px}
.ph{width:82px;height:82px;flex:none;border-radius:50%;padding:3px;background:linear-gradient(140deg,#6918e8,#4737e4 60%,#2a1c7a)}
.few .ph{width:98px;height:98px}
.ph img,.ph b{width:100%;height:100%;border-radius:50%;object-fit:cover;background:#1d1838}
.ph b{display:flex;align-items:center;justify-content:center;font:600 26px/1 Poppins;color:#b9a6ff}
.info{flex:1;min-width:0}
.info .n{font:600 22px/32px Poppins;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.info .d{font:400 15px/1.35 Poppins;color:#b8b8c7;max-height:41px;overflow:hidden}
.co{width:104px;height:48px;flex:none;display:flex;align-items:center;justify-content:center}
.co img{max-width:100%;max-height:100%;object-fit:contain}
